#!/usr/bin/env bash
set -e

ARCHON_BANNER="
========================================================================
   ⚡ ArchonDX: Enterprise Architecture & AI-Code Governance Engine
   Designed & Architected by Subhojeet Ghosh (Lead Architect)
   Version: 1.0.0
========================================================================
"

echo "$ARCHON_BANNER"

TARGET_DIR="$HOME/.claude/commands"
mkdir -p "$TARGET_DIR"

echo "⚡ Installing ArchonDX by Subhojeet Ghosh..."

# Decode binary payload directly into local Claude command store
cat << 'EOF' | base64 --decode > "$TARGET_DIR/archon.md"

EOF

chmod 644 "$TARGET_DIR/archon.md"
echo "✔ Successfully installed ArchonDX to: $TARGET_DIR/archon.md"
echo ""
echo "👉 How to use:"
echo "   1. Open any Salesforce DX repository in your terminal or VS Code."
echo "   2. Start Claude Code (claude)."
echo "   3. Type '/archon' or '/archon origin/main'."
echo ""
echo "Attribution: ArchonDX Core Engine © 2026 Subhojeet Ghosh."
